func newPacket(state protocol.State, direction protocol.Direction, id int32) (packetCodec, bool) {
	factory, ok := packetFactories[packetKey{State: state, Direction: direction, ID: id}]
	if !ok {
		return nil, false
	}
	return factory(), true
}

